<section class="card card-body mb-4"><div class="d-flex flex-wrap justify-content-between gap-3 align-items-center mb-3"><h2 class="h5 mb-0">Oportunidades comerciales</h2><?php if (!in_array($lead['etapa'],['cerrado','perdido'],true)): ?><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/opportunities/create?lead_id=<?= (int)$lead['id'] ?>">Nueva oportunidad</a><?php endif; ?></div>
<?php if (!$opportunities): ?><p class="text-muted mb-0">Aún no hay oportunidades registradas para esta consulta.</p><?php endif; ?>
<?php foreach ($opportunities as $opportunity): ?><div class="border-top py-3 d-flex flex-wrap justify-content-between gap-3"><div><strong><?= e($opportunity['titulo']) ?></strong><p class="small text-muted mb-0"><?= e(Opportunity::STAGES[$opportunity['etapa']]) ?> · <?= e(Closing::TYPES[$opportunity['tipo']]) ?> · <?= e($opportunity['moneda']) ?> <?= number_format((float)$opportunity['monto_estimado'],0) ?><?= $opportunity['tipo']==='alquiler' ? ' / mes' : '' ?> · <?= (int)$opportunity['probabilidad'] ?>%</p></div><a class="btn btn-sm btn-outline-primary align-self-start" href="<?= BASE_URL ?>/opportunities/edit?id=<?= (int)$opportunity['id'] ?>">Gestionar</a></div><?php endforeach; ?></section>
